describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, so total is just the other child
      const p1 = new NoDiscountPolicy();
      const p2 = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("sum can exceed subtotal (Cart clamps later)", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(800);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Each returns min(800, 1000) = 800, sum = 1600 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100, remaining 900
      const p2 = new PercentageDiscountPolicy(10); // 10% of 900 = 90, remaining 810
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // total discount = 100 + 90 = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("order matters in chain mode", () => {
      const fixed = new FixedAmountDiscountPolicy(200);
      const pct = new PercentageDiscountPolicy(10);

      // fixed first: 200 off 1000 → 800 remaining, 10% of 800 = 80 → total 280
      const fixedFirst = new CompositeDiscountPolicy([fixed, pct], "chain");
      expect(fixedFirst.computeDiscountCents(1000)).toBe(280);

      // pct first: 10% of 1000 = 100 → 900 remaining, min(200,900) = 200 → total 300
      const pctFirst = new CompositeDiscountPolicy([pct, fixed], "chain");
      expect(pctFirst.computeDiscountCents(1000)).toBe(300);
    });

    it("chain clamps each step so it cannot exceed remaining", () => {
      const p1 = new FixedAmountDiscountPolicy(600);
      const p2 = new FixedAmountDiscountPolicy(600);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // Step1: min(600, 1000) = 600, remaining 400
      // Step2: min(600, 400) = 400, remaining 0
      // Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "chain");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });
});

