      // 8.75% of 1001 = 87.5875 → 87
      expect(calc.computeTaxCents(1001, "US-CA")).toBe(87);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("computes with 0 default rate when not provided", () => {
      const noDefault = new RegionalTaxCalculator({ "US": 0.1 });
      expect(noDefault.computeTaxCents(1000, "FR")).toBe(0);
      expect(noDefault.computeTaxCents(1000, "US")).toBe(100);
