      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service error");
