import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

function makeProduct(overrides: Partial<Product> & { id: string }): Product {
  return { name: overrides.id, unitPriceCents: 1000, ...overrides };
}

describe("Cart", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a product to the cart", () => {
      cart.add(makeProduct({ id: "p1" }), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding same product again", () => {
      const product = makeProduct({ id: "p1" });
      cart.add(product, 2);
      cart.add(product, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects zero quantity", () => {
      expect(() => cart.add(makeProduct({ id: "p1" }), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      expect(() => cart.add(makeProduct({ id: "p1" }), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(makeProduct({ id: "p1" }), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      expect(() =>
        cart.add(makeProduct({ id: "p1", unitPriceCents: -1 }), 1),
      ).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("returns true and removes existing product", () => {
      cart.add(makeProduct({ id: "p1" }), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      cart.add(makeProduct({ id: "p1" }), 2);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      cart.add(makeProduct({ id: "p1" }), 2);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("p1")).toBe(false); // confirms it was removed
    });

    it("throws for non-existent product", () => {
      expect(() => cart.updateQuantity("missing", 1)).toThrow(
        "Product missing is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      cart.add(makeProduct({ id: "p1" }), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(makeProduct({ id: "p1" }), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      cart.add(makeProduct({ id: "p1" }), 1);
      cart.add(makeProduct({ id: "p2" }), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("itemCount", () => {
    it("returns 0 for empty cart", () => {
      expect(cart.itemCount).toBe(0);
    });

    it("sums quantities across lines", () => {
      cart.add(makeProduct({ id: "p1" }), 2);
      cart.add(makeProduct({ id: "p2" }), 3);
      expect(cart.itemCount).toBe(5);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of the cart lines", () => {
      const prod = makeProduct({ id: "p1", unitPriceCents: 500 });
      cart.add(prod, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("p1");
      expect(snap[0].quantity).toBe(2);

      // Mutating the snapshot does not affect the cart
      (snap[0] as { quantity: number }).quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("empty cart has all-zero totals", () => {
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("computes subtotal from price * quantity", () => {
      cart.add(makeProduct({ id: "p1", unitPriceCents: 500 }), 3);
      cart.add(makeProduct({ id: "p2", unitPriceCents: 200 }), 2);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(1900); // 1500 + 400
    });

    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const c = new Cart({ discountPolicy, taxCalculator, shippingCalculator, region: "US-CA" });
      c.add(makeProduct({ id: "p1", unitPriceCents: 1000 }), 1);
      const totals = c.totals();

      // subtotal = 1000, discount = 200, discounted = 800
      expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
      // tax on discounted subtotal
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      // shipping gets lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );

      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      expect(totals.taxCents).toBe(80);
      expect(totals.shippingCents).toBe(500);
      expect(totals.totalCents).toBe(800 + 80 + 500); // 1380
    });

    it("clamps discount to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const c = new Cart({ discountPolicy });
      c.add(makeProduct({ id: "p1", unitPriceCents: 500 }), 1);
      const totals = c.totals();
      expect(totals.discountCents).toBe(500); // clamped to subtotal
      expect(totals.totalCents).toBe(0); // fully discounted
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const c = new Cart({ discountPolicy });
      c.add(makeProduct({ id: "p1", unitPriceCents: 500 }), 1);
      const totals = c.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const c = new Cart({ taxCalculator });
      c.add(makeProduct({ id: "p1", unitPriceCents: 500 }), 1);
      expect(c.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const c = new Cart({ shippingCalculator });
      c.add(makeProduct({ id: "p1", unitPriceCents: 500 }), 1);
      expect(c.totals().shippingCents).toBe(0);
    });

    it("defaults to US region when not configured", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const c = new Cart({ taxCalculator });
      c.add(makeProduct({ id: "p1" }), 1);
      c.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      cart.add(makeProduct({ id: "p1", unitPriceCents: 500 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      cart.add(makeProduct({ id: "p1", unitPriceCents: 500 }), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(600),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
      // New subtotal = 600 * 2 = 1200
      expect(result.totals.subtotalCents).toBe(1200);
      expect(result.lines[0].product.unitPriceCents).toBe(600);
    });

    it("checks inventory and proceeds when available", async () => {
      cart.add(makeProduct({ id: "p1" }), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("p1", 3);
      expect(result.totals.subtotalCents).toBe(3000);
    });

    it("throws InventoryError when available is false", async () => {
      cart.add(makeProduct({ id: "p1" }), 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(3);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      cart.add(makeProduct({ id: "p1" }), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 2,
        }),
      };

      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(InventoryError);
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const c = new Cart({ discountPolicy, region: "US-CA" });
      c.add(makeProduct({ id: "p1", unitPriceCents: 1000 }), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await c.checkout({ asyncTaxProvider });
      // subtotal = 1000, discount = 100, discounted = 900
      // tax = 10% of 900 = 90
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.discountCents).toBe(100);
      expect(result.totals.taxCents).toBe(90);
    });

    it("composes priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const c = new Cart({ shippingCalculator, region: "DE" });
      c.add(makeProduct({ id: "p1", unitPriceCents: 1000 }), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(800),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.19),
      };

      const result = await c.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // New subtotal = 800 * 2 = 1600 (no discount → discounted = 1600)
      // Tax = 19% of 1600 = 304
      // Shipping = 500
      expect(result.totals.subtotalCents).toBe(1600);
      expect(result.totals.discountCents).toBe(0);
      expect(result.totals.taxCents).toBe(304);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(1600 + 304 + 500);
    });

    it("propagates priceFetcher rejection", async () => {
      cart.add(makeProduct({ id: "p1" }), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });

    it("propagates asyncTaxProvider rejection", async () => {
      cart.add(makeProduct({ id: "p1" }), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service error");
    });

    it("first inventory denial wins when multiple products", async () => {
      cart.add(makeProduct({ id: "p1" }), 1);
      cart.add(makeProduct({ id: "p2" }), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: false, reason: "discontinued" })
          .mockResolvedValueOnce({ available: true }),
      };

      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("p1");
        expect(err.message).toBe("discontinued");
      }
    });

    it("generates default message when reason is absent", async () => {
      cart.add(makeProduct({ id: "p1" }), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain("p1");
      }
    });
  });
});

